INSERT INTO resources(id,slug,title,summary,description,type,canonical_url,platforms_json,license,pricing,icon,image,mobile_image,hero_title,media_alt,media_credit,media_kind,status,featured_rank,curated_rank,search_text,created_at,updated_at) VALUES('excalidraw','excalidraw','Excalidraw','Vẽ ý tưởng thành hình bằng bảng trắng trực tuyến.','Excalidraw là bảng vẽ ảo để phác thảo các sơ đồ có nét vẽ tay. Có thể dùng bản web hoặc tìm hiểu mã nguồn. Giấy phép MIT ở đây áp dụng cho mã nguồn; các dịch vụ hoặc gói thương mại có thể có điều khoản riêng.','online_tool','https://excalidraw.com/','["Web"]','MIT cho mã nguồn',NULL,'/assets/excalidraw-responsive.svg','/assets/excalidraw-promo.png',NULL,NULL,'Artwork giới thiệu Excalidraw từ kho chính thức, không phải screenshot','Excalidraw contributors · MIT. Artwork nguyên bản; icon thêm viewBox responsive, giữ đường nét/màu và lưu bản gốc.','artwork','published',NULL,0,'excalidraw ve y tuong thanh hinh bang bang trang truc tuyen. excalidraw la bang ve ao de phac thao cac so do co net ve tay. co the dung ban web hoac tim hieu ma nguon. giay phep mit o day ap dung cho ma nguon; cac dich vu hoac goi thuong mai co the co dieu khoan rieng. web sang tao hoc tap ve so do','2026-11-03T00:00:00Z','2026-11-03T00:00:00Z') ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,summary=excluded.summary,description=excluded.description,type=excluded.type,canonical_url=excluded.canonical_url,platforms_json=excluded.platforms_json,license=excluded.license,pricing=excluded.pricing,icon=excluded.icon,image=excluded.image,mobile_image=excluded.mobile_image,hero_title=excluded.hero_title,media_alt=excluded.media_alt,media_credit=excluded.media_credit,media_kind=excluded.media_kind,status=excluded.status,featured_rank=excluded.featured_rank,curated_rank=excluded.curated_rank,search_text=excluded.search_text,updated_at=excluded.updated_at;
