INSERT INTO resources(id,slug,title,summary,description,type,canonical_url,platforms_json,license,pricing,icon,image,mobile_image,hero_title,media_alt,media_credit,media_kind,status,featured_rank,curated_rank,search_text,created_at,updated_at) VALUES('godot','godot','Godot Engine','Tạo thế giới của riêng bạn với game engine 2D và 3D.','Godot Engine cung cấp môi trường tạo trò chơi 2D và 3D, với hệ thống node và scene. Engine được phát hành theo MIT; license của engine không cấp quyền cho artwork, âm thanh hoặc tài nguyên bên thứ ba trong trò chơi.','application','https://godotengine.org/','[]','MIT cho engine','Miễn phí','/assets/godot.svg','/assets/godot-editor.jpg',NULL,NULL,'Godot editor với TPS demo, screenshot từ kho godot-design chính thức','Icon: Andrea Calabro / Godot contributors. Screenshot: Godot Engine contributors · CC BY 4.0. Tệp không chỉnh sửa, chỉ đổi kích thước hiển thị.','screenshot','published',NULL,1,'godot engine tao the gioi cua rieng ban voi game engine 2d va 3d. godot engine cung cap moi truong tao tro choi 2d va 3d, voi he thong node va scene. engine duoc phat hanh theo mit; license cua engine khong cap quyen cho artwork, am thanh hoac tai nguyen ben thu ba trong tro choi. lap trinh sang tao phat trien game','2026-11-03T00:00:00Z','2026-11-03T00:00:00Z') ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,summary=excluded.summary,description=excluded.description,type=excluded.type,canonical_url=excluded.canonical_url,platforms_json=excluded.platforms_json,license=excluded.license,pricing=excluded.pricing,icon=excluded.icon,image=excluded.image,mobile_image=excluded.mobile_image,hero_title=excluded.hero_title,media_alt=excluded.media_alt,media_credit=excluded.media_credit,media_kind=excluded.media_kind,status=excluded.status,featured_rank=excluded.featured_rank,curated_rank=excluded.curated_rank,search_text=excluded.search_text,updated_at=excluded.updated_at;
