INSERT INTO resources(id,slug,title,summary,description,type,canonical_url,platforms_json,license,pricing,icon,image,mobile_image,hero_title,media_alt,media_credit,media_kind,status,featured_rank,curated_rank,search_text,created_at,updated_at) VALUES('obs-studio','obs-studio','OBS Studio','Ghi hình màn hình và phát trực tiếp từ nhiều nguồn.','OBS Studio là phần mềm ghi hình và phát trực tiếp. Có thể tổ chức màn hình, camera và âm thanh thành các scene. Nên thử âm thanh và quyền thiết bị trước khi ghi một bài giảng hoặc buổi trình bày.','application','https://obsproject.com/','["Windows","macOS","Linux"]',NULL,'Miễn phí',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'published',NULL,NULL,'obs studio ghi hinh man hinh va phat truc tiep tu nhieu nguon. obs studio la phan mem ghi hinh va phat truc tiep. co the to chuc man hinh, camera va am thanh thanh cac scene. nen thu am thanh va quyen thiet bi truoc khi ghi mot bai giang hoac buoi trinh bay. windows macos linux sang tao hoc tap ghi man hinh','2026-11-03T00:00:00Z','2026-11-03T00:00:00Z') ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,summary=excluded.summary,description=excluded.description,type=excluded.type,canonical_url=excluded.canonical_url,platforms_json=excluded.platforms_json,license=excluded.license,pricing=excluded.pricing,icon=excluded.icon,image=excluded.image,mobile_image=excluded.mobile_image,hero_title=excluded.hero_title,media_alt=excluded.media_alt,media_credit=excluded.media_credit,media_kind=excluded.media_kind,status=excluded.status,featured_rank=excluded.featured_rank,curated_rank=excluded.curated_rank,search_text=excluded.search_text,updated_at=excluded.updated_at;
