INSERT INTO resources(id,slug,title,summary,description,type,canonical_url,platforms_json,license,pricing,icon,image,mobile_image,hero_title,media_alt,media_credit,media_kind,status,featured_rank,curated_rank,search_text,created_at,updated_at) VALUES('visual-studio-code','visual-studio-code','Visual Studio Code','Soạn mã, duyệt dự án và làm việc với công cụ lập trình.','Visual Studio Code là trình soạn thảo mã với công cụ chỉnh sửa, điều hướng mã và debug. Bản tải chính thức được cung cấp cho Windows, macOS và Linux. Điều khoản bản phân phối khác với license của kho mã nguồn; mục này chưa xác minh chi tiết license.','application','https://code.visualstudio.com/','["Windows","macOS","Linux"]',NULL,'Miễn phí',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'published',NULL,NULL,'visual studio code soan ma, duyet du an va lam viec voi cong cu lap trinh. visual studio code la trinh soan thao ma voi cong cu chinh sua, dieu huong ma va debug. ban tai chinh thuc duoc cung cap cho windows, macos va linux. dieu khoan ban phan phoi khac voi license cua kho ma nguon; muc nay chua xac minh chi tiet license. windows macos linux lap trinh hoc lap trinh','2026-11-03T00:00:00Z','2026-11-03T00:00:00Z') ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,summary=excluded.summary,description=excluded.description,type=excluded.type,canonical_url=excluded.canonical_url,platforms_json=excluded.platforms_json,license=excluded.license,pricing=excluded.pricing,icon=excluded.icon,image=excluded.image,mobile_image=excluded.mobile_image,hero_title=excluded.hero_title,media_alt=excluded.media_alt,media_credit=excluded.media_credit,media_kind=excluded.media_kind,status=excluded.status,featured_rank=excluded.featured_rank,curated_rank=excluded.curated_rank,search_text=excluded.search_text,updated_at=excluded.updated_at;
