INSERT INTO resources(id,slug,title,summary,description,type,canonical_url,platforms_json,license,pricing,icon,image,mobile_image,hero_title,media_alt,media_credit,media_kind,status,featured_rank,curated_rank,search_text,created_at,updated_at) VALUES('powertoys','powertoys','Microsoft PowerToys','Khám phá bộ tiện ích tùy chỉnh cách làm việc trên Windows.','PowerToys là bộ tiện ích mã nguồn mở của Microsoft dành cho Windows. Các công cụ hỗ trợ quản lý cửa sổ, tùy chỉnh bàn phím và những thao tác làm việc thường ngày. Liên kết tài nguyên dẫn đến kho mã nguồn chính thức, có tài liệu cài đặt riêng.','repository','https://github.com/microsoft/PowerToys','["Windows"]',NULL,'Miễn phí',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'published',NULL,NULL,'microsoft powertoys kham pha bo tien ich tuy chinh cach lam viec tren windows. powertoys la bo tien ich ma nguon mo cua microsoft danh cho windows. cac cong cu ho tro quan ly cua so, tuy chinh ban phim va nhung thao tac lam viec thuong ngay. lien ket tai nguyen dan den kho ma nguon chinh thuc, co tai lieu cai dat rieng. windows van phong he dieu hanh tien ich windows','2026-11-03T00:00:00Z','2026-11-03T00:00:00Z') ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,summary=excluded.summary,description=excluded.description,type=excluded.type,canonical_url=excluded.canonical_url,platforms_json=excluded.platforms_json,license=excluded.license,pricing=excluded.pricing,icon=excluded.icon,image=excluded.image,mobile_image=excluded.mobile_image,hero_title=excluded.hero_title,media_alt=excluded.media_alt,media_credit=excluded.media_credit,media_kind=excluded.media_kind,status=excluded.status,featured_rank=excluded.featured_rank,curated_rank=excluded.curated_rank,search_text=excluded.search_text,updated_at=excluded.updated_at;
