INSERT INTO resources(id,slug,title,summary,description,type,canonical_url,platforms_json,license,pricing,icon,image,mobile_image,hero_title,media_alt,media_credit,media_kind,status,featured_rank,curated_rank,search_text,created_at,updated_at) VALUES('openttd','openttd','OpenTTD','Xây dựng và vận hành mạng lưới vận tải trong game mô phỏng.','OpenTTD là trò chơi mô phỏng vận tải mã nguồn mở. Dự án có nhiều loại phương tiện và cách tổ chức mạng lưới vận tải. License GPL của trò chơi không tự cấp quyền cho mọi gói đồ họa, âm thanh hoặc nội dung bên ngoài được đưa vào game.','game','https://www.openttd.org/','[]','GNU GPL version 2.0 cho trò chơi',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'published',NULL,NULL,'openttd xay dung va van hanh mang luoi van tai trong game mo phong. openttd la tro choi mo phong van tai ma nguon mo. du an co nhieu loai phuong tien va cach to chuc mang luoi van tai. license gpl cua tro choi khong tu cap quyen cho moi goi do hoa, am thanh hoac noi dung ben ngoai duoc dua vao game. giai tri mo phong van tai','2026-11-03T00:00:00Z','2026-11-03T00:00:00Z') ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,summary=excluded.summary,description=excluded.description,type=excluded.type,canonical_url=excluded.canonical_url,platforms_json=excluded.platforms_json,license=excluded.license,pricing=excluded.pricing,icon=excluded.icon,image=excluded.image,mobile_image=excluded.mobile_image,hero_title=excluded.hero_title,media_alt=excluded.media_alt,media_credit=excluded.media_credit,media_kind=excluded.media_kind,status=excluded.status,featured_rank=excluded.featured_rank,curated_rank=excluded.curated_rank,search_text=excluded.search_text,updated_at=excluded.updated_at;
