INSERT INTO resources(id,slug,title,summary,description,type,canonical_url,platforms_json,license,pricing,icon,image,mobile_image,hero_title,media_alt,media_credit,media_kind,status,featured_rank,curated_rank,search_text,created_at,updated_at) VALUES('ubuntu-desktop-guide','ubuntu-desktop-guide','Hướng dẫn cài Ubuntu Desktop','Đọc quy trình cài đặt Ubuntu từ tài liệu chính thức.','Tài liệu Ubuntu Desktop hướng dẫn quy trình cài hệ điều hành trên máy tính. Mục này chỉ liên kết đến hướng dẫn chính chủ, không tải lại ISO hoặc thực hiện cài đặt. Việc cài hệ điều hành có thể ảnh hưởng dữ liệu; cần đọc hướng dẫn và sao lưu trước khi thao tác.','operating_system_resource','https://ubuntu.com/desktop/docs/en/latest/tutorial/install-ubuntu-desktop/','["Web"]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'published',NULL,NULL,'huong dan cai ubuntu desktop doc quy trinh cai dat ubuntu tu tai lieu chinh thuc. tai lieu ubuntu desktop huong dan quy trinh cai he dieu hanh tren may tinh. muc nay chi lien ket den huong dan chinh chu, khong tai lai iso hoac thuc hien cai dat. viec cai he dieu hanh co the anh huong du lieu; can doc huong dan va sao luu truoc khi thao tac. web he dieu hanh hoc tap linux','2026-11-03T00:00:00Z','2026-11-03T00:00:00Z') ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,summary=excluded.summary,description=excluded.description,type=excluded.type,canonical_url=excluded.canonical_url,platforms_json=excluded.platforms_json,license=excluded.license,pricing=excluded.pricing,icon=excluded.icon,image=excluded.image,mobile_image=excluded.mobile_image,hero_title=excluded.hero_title,media_alt=excluded.media_alt,media_credit=excluded.media_credit,media_kind=excluded.media_kind,status=excluded.status,featured_rank=excluded.featured_rank,curated_rank=excluded.curated_rank,search_text=excluded.search_text,updated_at=excluded.updated_at;
