INSERT INTO resources(id,slug,title,summary,description,type,canonical_url,platforms_json,license,pricing,icon,image,mobile_image,hero_title,media_alt,media_credit,media_kind,status,featured_rank,curated_rank,search_text,created_at,updated_at) VALUES('awesome-selfhosted','awesome-selfhosted','Awesome Selfhosted','Khám phá bộ sưu tập phần mềm và dịch vụ có thể tự host.','Awesome Selfhosted là danh sách tuyển chọn các dịch vụ mạng và ứng dụng web có thể triển khai trên máy chủ của bạn. Mỗi dự án trong danh sách có yêu cầu vận hành và license riêng; việc có tên trong danh sách không bảo chứng an toàn hoặc phù hợp cho mọi môi trường.','collection','https://github.com/awesome-selfhosted/awesome-selfhosted','[]',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'published',NULL,NULL,'awesome selfhosted kham pha bo suu tap phan mem va dich vu co the tu host. awesome selfhosted la danh sach tuyen chon cac dich vu mang va ung dung web co the trien khai tren may chu cua ban. moi du an trong danh sach co yeu cau van hanh va license rieng; viec co ten trong danh sach khong bao chung an toan hoac phu hop cho moi moi truong. lap trinh tu host','2026-11-03T00:00:00Z','2026-11-03T00:00:00Z') ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,summary=excluded.summary,description=excluded.description,type=excluded.type,canonical_url=excluded.canonical_url,platforms_json=excluded.platforms_json,license=excluded.license,pricing=excluded.pricing,icon=excluded.icon,image=excluded.image,mobile_image=excluded.mobile_image,hero_title=excluded.hero_title,media_alt=excluded.media_alt,media_credit=excluded.media_credit,media_kind=excluded.media_kind,status=excluded.status,featured_rank=excluded.featured_rank,curated_rank=excluded.curated_rank,search_text=excluded.search_text,updated_at=excluded.updated_at;
