INSERT INTO resources(id,slug,title,summary,description,type,canonical_url,platforms_json,license,pricing,icon,image,mobile_image,hero_title,media_alt,media_credit,media_kind,status,featured_rank,curated_rank,search_text,created_at,updated_at) VALUES('gh-274495425','gh-274495425','remotion','Remotion là công cụ tạo video bằng lập trình sử dụng React, cho phép thiết kế, chỉnh sửa tương tác và tự động hóa render video hàng loạt.','Remotion cho phép tạo video bằng lập trình với React, chỉnh sửa tương tác và tự động hóa render. Dự án có Free License cho nhóm đủ điều kiện và Company License cho các trường hợp khác; cần đọc LICENSE.md của phiên bản sử dụng.','repository','https://github.com/remotion-dev/remotion','[]','Remotion License — Free License / Company License (có điều kiện)','Freemium · Free: Miễn phí cho cá nhân, tổ chức phi lợi nhuận và doanh nghiệp tối đa 3 nhân viên; trường hợp khác cần Company License. Xem điều khoản và phiên bản áp dụng.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'published',NULL,NULL,'remotion remotion la cong cu tao video bang lap trinh su dung react, cho phep thiet ke, chinh sua tuong tac va tu dong hoa render video hang loat. remotion cho phep tao video bang lap trinh voi react, chinh sua tuong tac va tu dong hoa render. du an co free license cho nhom du dieu kien va company license cho cac truong hop khac; can doc license.md cua phien ban su dung. sang tao','2026-11-05T08:40:09.982Z','2026-11-05T08:52:45.124Z') ON CONFLICT(id) DO UPDATE SET slug=excluded.slug,title=excluded.title,summary=excluded.summary,description=excluded.description,type=excluded.type,canonical_url=excluded.canonical_url,platforms_json=excluded.platforms_json,license=excluded.license,pricing=excluded.pricing,icon=excluded.icon,image=excluded.image,mobile_image=excluded.mobile_image,hero_title=excluded.hero_title,media_alt=excluded.media_alt,media_credit=excluded.media_credit,media_kind=excluded.media_kind,status=excluded.status,featured_rank=excluded.featured_rank,curated